{
  "response_type": "hierarchical_reduction_runtime_implementation",
  "architecture_summary": "A fully generic, config-driven hierarchical reduction runtime for bounded context processing. Raw input is partitioned into batches strictly bounded by divider.max_kb. Reduction iteration index B determines evaluator class selection via configurable rules (B == 0 selecting raw-evidence base evaluators, B > 0 selecting proof-carrying decision reducers). Each evaluation invocation executes in a fresh, isolated Node.js child process to eliminate conversation context leakage. Sequential execution validates responses using purely mechanical criteria (transport integrity, deterministic JSON/key recovery, and hard response-size ratio ceilings). Bounded corrective retries receive only mechanical failure payloads without semantic judgment. Upon round completion, aggregate responses are tested against termination criteria; when convergence <= max_kb is attained, a single final evaluator call synthesizes the final proof-carrying decision.",
  "iterator_control": {
    "B_definition": "Integer counter B >= 0 representing the hierarchical reduction round. B = 0 is the initial raw evidence evaluation phase. Each subsequent reduction cycle increments B by 1 after repartitioning the aggregated proof-carrying decisions into batches of size <= divider.max_kb.",
    "when_B_equals_0": "Evaluates raw context batches using the configured base_evaluator class, producing initial proof-carrying decisions with summaries, minimal facts with provenance, and decisions.",
    "when_B_greater_than_0": "Evaluates aggregated decisions from round B - 1 partitioned into <= divider.max_kb batches using the configured decision_evaluator class, compressing prose and reconciling proofs while preserving provenance chains.",
    "round_completion_rule": "After all batches in round B complete sequentially, serialize and tally all output payload byte sizes. Calculate aggregate_response_kb = total_bytes / 1024.",
    "termination_rule": "Evaluate termination_test: aggregate_response_kb / divider.max_kb <= 1.0. If false, repartition serialized responses into new batches of <= divider.max_kb, increment B, and continue. If true, halt batch reduction and execute the final invocation.",
    "final_invocation_rule": "When termination_test evaluates to true, do not divide remaining context. Execute exactly one fresh evaluator invocation on the complete aggregated response set using the configured final_evaluator_class (decision_evaluator), persist the output as the final evaluation artifact, and exit."
  },
  "mechanical_validation": {
    "allowed_tests": [
      "transport_success",
      "required_keys_recovery",
      "hard_response_size_ceiling"
    ],
    "semantic_validation_prohibited": true,
    "system_error_behavior": "Transport or network failures (non-200 HTTP, network timeouts, process crashes) trigger up to max_transport_retries (default 1) fresh process invocations. If the retry fails, persist a system_failure record for that batch and advance to the next batch.",
    "malformed_json_behavior": "Malformed JSON is not an immediate failure or retry cause. Deterministic regex and substring boundary recovery extract the outermost JSON object. If all required keys specified by the active response contract can be recovered, the response is accepted and normalized.",
    "hard_size_behavior": "Enforces hard_size_rule (ratio_of_batch_max <= 0.5 of input batch bytes or hard ceiling). Exceeding the soft preferred_response_size is tolerated; violating the hard ceiling triggers the corrective attempt policy.",
    "corrective_attempt_behavior": "When required keys cannot be recovered or the hard response size rule is violated, exactly one fresh corrective evaluator is spawned. It receives the identical batch context, the prior invalid response, the mechanical diagnostic error, and the active task/contract. If the corrective attempt also fails mechanical validation, persist the failure record and continue; never recurse."
