      "criteria": [
        "Operate strictly on prior proof-carrying decisions; do not expect raw context.",
        "Merge redundant facts and retain provenance lineage across all prior decisions.",
        "Preserve open contradictions as INDETERMINATE.",
        "Aggressively compress prose while preserving all actionable decision claims."
      ],
      "response_contract": {
        "expected_type": "hierarchical_reduction_decision",
